// Package: Microsoft.Extensions.AI
// Package: Microsoft.Extensions.Caching.Memory

using Microsoft.Extensions.AI;
using Microsoft.Extensions.Caching.Memory;

public sealed class TokenBudgetService
{
    private readonly IMemoryCache _cache;
    private readonly IChatClient _chatClient;

    public TokenBudgetService(
        IMemoryCache cache,
        IChatClient chatClient)
    {
        _cache = cache;
        _chatClient = chatClient;
    }

    public async Task<ChatResponse> GenerateWithBudgetAsync(
        string prompt,
        int maxInputTokens = 4096,
        int maxOutputTokens = 1024,
        decimal maxCostUsd = 0.05m,
        CancellationToken ct = default)
    {
        // Step 1: count input tokens using the chat client's built-in tokenizer
        var tokenizer = _chatClient.GetService<ITokenizer>();
        var inputTokens = tokenizer != null
            ? tokenizer.CountTokens(prompt)
            : prompt.Length / 4; // rough fallback estimate

        if (inputTokens > maxInputTokens)
            throw new InvalidOperationException(
                $"Prompt exceeds input token budget: {inputTokens} > {maxInputTokens}");

        // Step 2: check cache for identical prompt
        var cacheKey = ComputeCacheKey(prompt);
        if (_cache.TryGetValue(cacheKey, out ChatResponse? cached))
            return cached;

        var options = new ChatOptions { MaxOutputTokens = maxOutputTokens, Temperature = 0.2f };
        var response = await _chatClient.GetResponseAsync(
            new[] { new ChatMessage(ChatRole.User, prompt) },
            options,
            ct);

        // Step 3: read actual usage from the response
        var usage = response.Usage ?? new TokenUsage(inputTokens, 0);
        var estimatedCost = EstimateCost(usage.InputTokenCount, usage.OutputTokenCount);
        if (estimatedCost > maxCostUsd)
            throw new InvalidOperationException(
                $"Estimated cost {estimatedCost:C} exceeds budget {maxCostUsd:C}");

        // Step 4: cache successful response for 15 minutes
        _cache.Set(cacheKey, response, TimeSpan.FromMinutes(15));
        return response;
    }

    private static decimal EstimateCost(int inputTokens, int outputTokens)
    {
        // Sample gpt-4o-mini rate: $0.15 per 1M input tokens, $0.60 per 1M output tokens
        const decimal inputRatePerM = 0.00015m;
        const decimal outputRatePerM = 0.00060m;
        var cost = (inputTokens * inputRatePerM + outputTokens * outputRatePerM) / 1_000_000m;

        // Expected output: Cost = $0.0000018 for a 12-token prompt and 200-character response
        return cost;
    }

    private static string ComputeCacheKey(string prompt)
    {
        var hash = System.Security.Cryptography.SHA256.HashData(
            System.Text.Encoding.UTF8.GetBytes(prompt));
        return Convert.ToHexString(hash)[..12];
    }
}

// Sample usage
var budgetService = new TokenBudgetService(
    new MemoryCache(new MemoryCacheOptions()),
    new OpenAIClient("your-api-key").AsChatClient("gpt-4o-mini"));

try
{
    var response = await budgetService.GenerateWithBudgetAsync(
        prompt: "Explain RAG in 2 sentences.",
        maxInputTokens: 4096,
        maxOutputTokens: 256,
        maxCostUsd: 0.10m);

    Console.WriteLine(response.Messages.Last().Text);
}
catch (InvalidOperationException ex)
{
    Console.WriteLine($"Budget guard rejected request: {ex.Message}");
}

