using Microsoft.Extensions.AI;
using Microsoft.Extensions.Caching.Memory;

public sealed class CachingRetriever
{
    private readonly IMemoryCache _cache;
    private readonly IEmbeddingGenerator _embeddingGenerator;
    private readonly IVectorStore _vectorStore;

    public CachingRetriever(
        IMemoryCache cache,
        IEmbeddingGenerator embeddingGenerator,
        IVectorStore vectorStore)
    {
        _cache = cache;
        _embeddingGenerator = embeddingGenerator;
        _vectorStore = vectorStore;
    }

    public async Task<IReadOnlyList<VectorSearchResult>> RetrieveAsync(
        string query,
        int topK = 5,
        CancellationToken ct = default)
    {
        var cacheKey = $"retrieval:{ComputeQueryHash(query)}:{topK}";

        if (_cache.TryGetValue(cacheKey, out IReadOnlyList<VectorSearchResult>? cached))
        {
            // Expected output: Returned cached results, avoiding vector search
            return cached;
        }

        var embedding = await _embeddingGenerator.GenerateAsync(query, ct);
        var results = await _vectorStore.SearchAsync<VectorStoreRecord>(
            "rag-documents",
            embedding.Vector,
            new VectorSearchOptions { Top = topK },
            ct);

        // Cache for 10 minutes; invalidate when documents change
        _cache.Set(cacheKey, results, TimeSpan.FromMinutes(10));

        return results;
    }

    private static string ComputeQueryHash(string query)
    {
        var hash = System.Security.Cryptography.SHA256.HashData(
            System.Text.Encoding.UTF8.GetBytes(query));
        return Convert.ToHexString(hash)[..12];
    }
}

// Sample usage
var retriever = new CachingRetriever(
    new MemoryCache(new MemoryCacheOptions()),
    new OpenAIClient("your-api-key").AsEmbeddingGenerator("text-embedding-3-small"),
    new YourVectorStore());

